import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {World} from '../world.js';import {SIDE_CAMPAIGNS,REGIONS,frontierState,frontierObjects,commission} from '../frontiers.js';import {FRONTIER_BESTIARY,frontierEnemy} from '../repertoire.js?v=5.6.0';import {makeEnemy,Battle} from '../battle.js?v=5.6.0';import {findPath} from '../navigation.js';
const data=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));
function setup(){let dialog;const w=new World(data,{onDialog:d=>dialog=d,onBattle:()=>{}});w.state.chapter=24;w.state.mode='field';return {w,get d(){return dialog;},close(){dialog?.after?.();w.state.mode='field';}};}
test('60 connected frontier areas preserve every exit and objective approach',()=>{const {w}=setup(),rooms=w.data.scenes.filter(s=>s.biome&&s.fieldOrigin===undefined);assert.equal(rooms.length,60);for(const s of rooms){for(const o of s.objects){const p=o.xy;if(!p)continue;assert.equal(s.floor[p[1]][p[0]],'.',s.key+' '+o.label);assert.ok(findPath(s,s.arrive,p,1).length||Math.hypot(s.arrive[0]-p[0],s.arrive[1]-p[1])<=1.5,s.key+' '+o.label);if(o.type==='portal'&&o.to!=='hub'){const to=w.data.scenes.find(r=>r.key===o.to);assert.ok(to);assert.equal(to.floor[o.arrive[1]][o.arrive[0]],'.');}}}});
test('all 240 commissions complete through survey, repair, encounter and one-time report',()=>{const h=setup(),w=h.w,flags=JSON.stringify(w.state.flags);assert.equal(SIDE_CAMPAIGNS.length,240);assert.equal(new Set(SIDE_CAMPAIGNS.map(c=>c.id)).size,240);for(const c of SIDE_CAMPAIGNS){commission(w,c);h.d.choices[0].action();assert.equal(w.scene.location,2000+c.regionIndex*5+c.area);w.state.mode='field';w.interact(w.objects().find(o=>o.frontierStep===0));h.close();assert.equal(frontierState(w).stages[c.id],1);w.interact(w.objects().find(o=>o.frontierStep===1));const choices=h.d.choices;choices[(c.answer+1)%3].action();h.close();assert.equal(frontierState(w).stages[c.id],1);w.interact(w.objects().find(o=>o.frontierStep===1));h.d.choices[c.answer].action();h.close();const patrol=frontierObjects(w)[0];assert.ok(patrol);w.interact(patrol);assert.ok(w.currentBattle);w.winBattle();h.close();assert.equal(frontierObjects(w).length,0);assert.equal(frontierState(w).stages[c.id],3);commission(w,c);const gold=w.state.gold;h.d.choices[0].action();h.close();assert.equal(w.state.gold,gold+c.reward);commission(w,c);h.close();assert.equal(w.state.gold,gold+c.reward);}assert.equal(frontierState(w).claimed.length,240);assert.equal(JSON.stringify(w.state.flags),flags);const saved=w.save(),copy=setup().w;copy.restore(saved);assert.deepEqual(copy.state.frontiers,w.state.frontiers);});
test('all 96 frontier profiles enter real battle and serialize without losing their identity',()=>{assert.equal(FRONTIER_BESTIARY.length,96);assert.equal(new Set(FRONTIER_BESTIARY.map(s=>s.id)).size,96);const {w}=setup();for(const s of FRONTIER_BESTIARY){const e=frontierEnemy(makeEnemy('guard',s.chapter),s.id);assert.ok(Number.isFinite(e.armor));e.x=25;e.y=20;const b=new Battle({heroes:w.activeHeroes,enemies:[e],chapter:s.chapter});b.planEnemy(e);assert.ok(e.intent);const snapshot=JSON.parse(JSON.stringify(b.snapshot()));assert.equal(snapshot.enemies[0].species,s.id);assert.equal(snapshot.enemies[0].trait,s.trait);}const encountered=new Set(SIDE_CAMPAIGNS.flatMap(c=>c.species));for(const s of FRONTIER_BESTIARY)assert.ok(encountered.has(s.id),s.id+' has an encounter');});
test('unfinished jobs survive save and switching jobs without claiming their reward',()=>{const h=setup(),w=h.w,c=SIDE_CAMPAIGNS[0];commission(w,c);h.d.choices[0].action();w.state.mode='field';w.interact(w.objects().find(o=>o.frontierStep===0));h.close();const copy=setup().w;copy.restore(w.save());assert.equal(frontierState(copy).active,c.id);assert.equal(frontierState(copy).stages[c.id],1);assert.equal(frontierState(copy).claimed.length,0);});
test('older off-route frontier saves settle onto walkable ground',()=>{const {w}=setup();w.state.scene=2000;w.state.x=1.5;w.state.y=1.5;const copy=setup().w;copy.restore(w.save());assert.ok(copy.walkable(copy.state.x,copy.state.y));assert.equal(copy.state.scene,2000);});
